def median(values):
    if not values:
        raise ValueError("median requires at least one data point")

    ordered = sorted(values)
    n = len(ordered)

    if n % 2 == 1:
        # Odd number of items
        return ordered[n // 2]
    else:
        # Even number of items - return mean of two middle values
        mid1 = ordered[n // 2 - 1]
        mid2 = ordered[n // 2]
        return (mid1 + mid2) / 2

